// Generate the host half of `overlay/astra/jar.mn` from the filesystem.
//
// The app half is generated by `ui/app/scripts/stage-chrome.mjs`, but that
// script only runs as part of `bun run --filter @astra/frame build:chrome`.
// A host-only change (a new `overlay/astra/host/*.sys.mjs` or schema) must not
// need a full app build, so this generator is standalone: `build:chrome` and
// the packaged build both invoke it, and it can be run on its own before
// `forge overlay` copies the overlay into the engine.
//
// The list is sorted, so a second run is a no-op. Only the BEGIN/END HOST API
// block is rewritten; every other line in jar.mn is left byte-for-byte alone.
//
// Usage: node tools/stage-host-jar.mjs
// Stdlib only.

import { readdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const HOST = path.join(ROOT, "overlay", "astra", "host");
const JAR = path.join(ROOT, "overlay", "astra", "jar.mn");

export const BEGIN =
  "  # BEGIN HOST API (generated by `node tools/stage-host-jar.mjs`; do not hand-edit; BootSidecar.sys.mjs is not packaged)";
export const END = "  # END HOST API";

// Named, not inferred: the one host module the manifest must not carry.
// `BootSidecar.sys.mjs` is a compatibility re-export (HOST_API_v1.md §Modules)
// and is deliberately absent from the packaged tree. If a second exception is
// ever needed, add it here with its reason; do not let a file disappear
// silently.
const NOT_PACKAGED = new Map([
  ["BootSidecar.sys.mjs", "compatibility re-export; HOST_API_v1.md §Modules"],
]);

async function filesIn(dir, extension) {
  const entries = await readdir(dir, { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && entry.name.endsWith(extension))
    .map((entry) => entry.name)
    .sort();
}

const modules = (await filesIn(HOST, ".sys.mjs")).filter((name) => {
  const reason = NOT_PACKAGED.get(name);
  if (!reason) return true;
  console.log(`stage-host-jar: skipping ${name} (${reason})`);
  return false;
});
const schemas = await filesIn(path.join(HOST, "schemas"), ".json");

const lines = [
  ...modules.map(
    (name) => `  content/astra/res/host/${name} (host/${name})`,
  ),
  ...schemas.map(
    (name) => `  content/astra/res/host/schemas/${name} (host/schemas/${name})`,
  ),
];

const source = await readFile(JAR, "utf8");
const start = source.indexOf(BEGIN);
const end = source.indexOf(END);
if (start === -1 || end === -1 || end < start) {
  throw new Error(`stage-host-jar: jar.mn HOST API markers missing (${JAR})`);
}

const before = source.slice(0, start);
const after = source.slice(end + END.length);
const block = [BEGIN, ...lines, END].join("\n");
const next = `${before}${block}${after}`;
if (next === source) {
  console.log(
    `stage-host-jar: ${modules.length} host modules + ${schemas.length} schemas already current`,
  );
} else {
  await writeFile(JAR, next);
  console.log(
    `stage-host-jar: wrote ${modules.length} host modules + ${schemas.length} schemas to jar.mn`,
  );
}
